const LBLC = new Map(); function labelSprite(text) { if (!LBLC.has(text)) { const c = document.createElement("canvas"); c.width = 512; c.height = 72; const g = c.getContext("2d"); g.font = "bold 36px sans-serif"; const w = Math.min(500, g.measureText(text).width + 36); g.fillStyle = "rgba(20,22,26,0.78)"; g.beginPath(); g.roundRect((512 - w) / 2, 4, w, 64, 16); g.fill(); g.fillStyle = "#f8e8a8"; g.textAlign = "center"; g.fillText(text, 256, 50); const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; LBLC.set(text, t); }
  const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: LBLC.get(text), depthTest: false, transparent: true })); sp.renderOrder = 20; sp.scale.set(1.6, 0.225, 1); scene.add(sp); return sp; }
