  for (const c of CREW) if (c.label) scene.remove(c.label); for (const m of MACT) if (m.label) scene.remove(m.label); CREW = []; MACT = []; const spec = CREWS[i]; if (!spec) return;
  for (const name of spec.m) { const M = MACH[name], P = name === "sawstand" && i === 17 ? [F(26), FL1, F(18.4), 0] : name === "mixer" && i === 3 ? [-F(18), 0, MID + F(26), Math.PI / 2] : name === "exc" && i === 8 ? [F(20), 0, -F(24), 0] : name === "skid" && i === 8 ? [-F(2.5), 0, F(4), 0] : MPOS[name]; M.g.position.set(P[0], P[1], P[2]); M.g.rotation.y = P[3]; M.g.visible = true; MACT.push({ name, M, label: labelSprite(MNAME[name]) }); }
